window.RP_SESSION={"id":"S-297160f0ba37","messages":[{"id":"RP-II-0082985","time":"2026-04-14T20:04:00+09:00","room":"RP II","name":"캐너리 지엘리히의 종료 등록자","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!졸업 캐너리 지엘리히","characters":[]},{"id":"RP-II-0082986","time":"2026-04-14T20:04:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"[권한이 없습니다.]","characters":[]},{"id":"RP-II-0082987","time":"2026-04-14T20:05:00+09:00","room":"RP II","name":"캐너리 지엘리히의 종료 등록자","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!졸업 캐너리 지엘리히","characters":[]},{"id":"RP-II-0082988","time":"2026-04-14T20:05:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"['캐너리 지엘리히' 의 여정을 마치고 모험에서 떠납니다. 정말 그렇게 하시겠습니까?]\n\n[예] / [아니오]\n\n※ 모험이 종료된 캐릭터는 복귀할 수 없습니다.","characters":[]},{"id":"RP-II-0082989","time":"2026-04-14T20:05:00+09:00","room":"RP II","name":"캐너리 지엘리히의 종료 등록자","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"예","characters":[]},{"id":"RP-II-0082990","time":"2026-04-14T20:05:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"당신의 여정은 탐탁지 못했습니다.\n\n모험을 떠나온 지 꽤나 되었으나,\n당신의 이름을 기억하는 이는 소수에 불과했을 것입니다.\n\n누군가는 당신을,\n\n큰 뜻을 품고 나왔으나 현실의 벽에 부딪혀\n이내 고향으로 돌아간 작은 모험가로\n\n어쩌면 잠깐의 일탈을 마치고 현실에 수긍해\n가업을 잇게 된 변방의 소시민으로\n\n또 누군가는,\n또 다른 여정길에 올랐다가\n비석 없이 자리 잡은 이름 없는 무덤으로 남았다고 말할지도 모르겠습니다.\n\n훗날,\n당신은 모든 것을 마치고 영혼길에 오릅니다.\n\n빛나는 꿈을 향해 뻗던 손과\n그늘진 얼굴은\n\n조용히 두 눈을 감습니다...","characters":[]},{"id":"RP-II-0082991","time":"2026-04-14T20:12:00+09:00","room":"RP II","name":"캐너리 지엘리히의 종료 등록자","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-II-0082992","time":"2026-04-14T20:12:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
